function add(a: int, b: int): int { return a + b; }
export function test(): int {
  let f: (a: int, b: int) => int = add;
  return f(20, 22);
}

function dbl(x: int): int { return x * 2; }
export function test(): int {
  let f = dbl;
  return f(21);
}

function inc(x: int): int { return x + 1; }
function apply(f: (x: int) => int, v: int): int { return f(v); }
export function test(): int { return apply(inc, 41); }

function pick(flag: boolean, yes: string, no: string): string {
  if (flag) { return yes; }
  return no;
}
function choose(f: (flag: boolean, yes: string, no: string) => string, flag: boolean): string {
  return f(flag, "jvm", "lua");
}
export function test(): string { return choose(pick, true); }

function inc(x: int): int { return x + 1; }
function picker(): (x: int) => int { return inc; }
export function test(): int { return picker()(41); }

function noop(): null { return; }
function withNull(n: null): int { return 42; }
export function test(): int {
  let nf: () => null = noop;
  nf();
  let wn: (n: null) => int = withNull;
  return wn(null);
}

function inc(x: int): int { return x + 1; }
export function test(): int {
  let f: (x: int) => int = inc;
  let g: (x: int) => int = inc;
  if (f === g) { return 1; }
  return 0;
}

function inc(x: int): int { return x + 1; }
function twice(f: (x: int) => int, v: int): int { return f(f(v)); }
export function test(): int { return twice(inc, 20); }

export function test(): int {
